sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        g_form.hideFieldMsg('renewal_due', true);
        return;
    }

    var validFrom = g_form.getValue('valid_from');
    var validTo = g_form.getValue('valid_to');
    var renewalDue = newValue;
    g_form.hideFieldMsg('renewal_due', true);

    if (validFrom && renewalDue < validFrom) {
        g_form.showFieldMsg('renewal_due', 'Renewal Due date cannot be earlier than Valid From date (' + validFrom + ').', 'error');
    } else if (validTo && renewalDue > validTo) {
        g_form.showFieldMsg('renewal_due', 'Renewal Due date cannot be later than Valid To date (' + validTo + ').', 'error');
    }
}
